    def _sm_resolve_units(self, selected: Any) -> list[Any]:
        if selected is None:
            return []
        if isinstance(selected, (list, tuple, set)):
            values = list(selected)
        else:
            values = [selected]
        out: list[Any] = []
        seen: set[str] = set()
        for value in list(values or []):
            root = self._sm_root(value)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            out.append(root)
        return out

    def _sm_unit_in_candidates(self, root: Any, candidates: list[Any]) -> bool:
        if root is None:
            return False
        root_id = self._sm_sort_key(root)
        for candidate in list(candidates or []):
            candidate_root = self._sm_root(candidate)
            if candidate_root is None:
                continue
            if candidate_root is root:
                return True
            candidate_id = self._sm_sort_key(candidate_root)
            if root_id and candidate_id and root_id == candidate_id:
                return True
        return False

    @staticmethod
    def _sm_unit_models(unit: Any) -> list[Any]:
        if unit is None:
            return []
        get_models = getattr(unit, "get_attached_unit_models", None)
        if callable(get_models):
            return list(get_models() or [])
        return list(getattr(unit, "models", []) or [])

    def _sm_unit_has_ranged_weapon(self, unit: Any) -> bool:
        for model in self._sm_unit_models(unit):
            is_alive_attr = getattr(model, "is_alive", True)
            is_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
            if not is_alive:
                continue
            for wargear in list(getattr(model, "wargear", []) or []):
                if wargear is None:
                    continue
                is_ranged = getattr(wargear, "is_ranged", None)
                if callable(is_ranged) and bool(is_ranged()):
                    return True
        return False

    @staticmethod
    def _sm_wargear_has_keyword(wargear: Any, keyword: str) -> bool:
        target = str(keyword or "").strip().upper()
        if wargear is None or not target:
            return False
        checker_name = f"is_{target.lower().replace(' ', '_').replace('-', '_')}"
        checker = getattr(wargear, checker_name, None)
        if callable(checker) and bool(checker()):
            return True
        get_keywords = getattr(wargear, "get_keywords", None)
        if callable(get_keywords):
            try:
                keywords = list(get_keywords() or [])
            except TypeError:
                keywords = []
            for value in keywords:
                text = str(value or "").strip().upper()
                if text == target or text.startswith(f"{target} "):
                    return True
        profiles = getattr(wargear, "profiles", None)
        if isinstance(profiles, dict):
            for profile in list(profiles.values()):
                get_keywords = getattr(profile, "get_keywords", None)
                if not callable(get_keywords):
                    continue
                try:
                    keywords = list(get_keywords() or [])
                except TypeError:
                    continue
                for value in keywords:
                    text = str(value or "").strip().upper()
                    if text == target or text.startswith(f"{target} "):
                        return True
        return False

    @staticmethod
    def _sm_model_temporary_weapon_has_keyword(
        model: Any,
        weapon_name: str,
        keyword: str,
        *,
        attack_type: str = "",
    ) -> bool:
        getter = getattr(model, "get_temporary_weapon_keyword_bonuses", None)
        if not callable(getter):
            return False
        target = str(keyword or "").strip().upper()
        attack_type_key = str(attack_type or "").strip().lower()
        for entry in list(getter(weapon_name) or []):
            if not isinstance(entry, dict):
                continue
            entry_attack_type = str(entry.get("attack_type", "") or "").strip().lower()
            if attack_type_key and entry_attack_type not in {"", "any", attack_type_key}:
                continue
            entry_keyword = str(entry.get("keyword", "") or "").strip().upper()
            if entry_keyword == target or entry_keyword.startswith(f"{target} "):
                return True
        return False

    def _sm_unit_has_torrent_ranged_weapon(self, unit: Any) -> bool:
        for model in self._sm_unit_models(unit):
            is_alive_attr = getattr(model, "is_alive", True)
            is_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
            if not is_alive:
                continue
            for wargear in list(getattr(model, "wargear", []) or []):
                if wargear is None:
                    continue
                is_ranged = getattr(wargear, "is_ranged", None)
                if not callable(is_ranged) or not bool(is_ranged()):
                    continue
                is_torrent = getattr(wargear, "is_torrent", None)
                has_torrent = bool(callable(is_torrent) and is_torrent())
                if not has_torrent:
                    get_keywords = getattr(wargear, "get_keywords", None)
                    if callable(get_keywords):
                        keywords = {
                            str(keyword or "").strip().upper()
                            for keyword in list(get_keywords() or [])
                            if str(keyword or "").strip()
                        }
                        has_torrent = "TORRENT" in keywords
                if has_torrent:
                    return True
        return False

    def _sm_unit_visible_to_unit(self, source_unit: Any, target_unit: Any) -> bool:
        source_root = self._sm_root(source_unit)
        target_root = self._sm_root(target_unit)
        game_map = self._sm_game_map()
        if source_root is None or target_root is None:
            return False
        if game_map is None:
            return True
        has_los = getattr(source_root, "_has_line_of_sight_to_target", None)
        if not callable(has_los):
            return True
        for model in self._sm_unit_models(source_root):
            is_alive_attr = getattr(model, "is_alive", True)
            is_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
            if not is_alive:
                continue
            try:
                if bool(has_los(model, target_root, game_map)):
                    return True
            except Exception:
                continue
        return False

    def _sm_alive_model_count(self, unit: Any) -> int:
        count = 0
        for model in self._sm_unit_models(unit):
            is_alive_attr = getattr(model, "is_alive", True)
            is_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
            if is_alive:
                count += 1
        return int(count)

    def _sm_resolve_selected_model(self, selection: Any, models: list[Any]) -> Any:
        if selection is None:
            return None
        for model in list(models or []):
            if model is selection:
                return model
        selection_id = str(get_entity_id(selection) or selection or "")
        if not selection_id:
            return None
        for model in list(models or []):
            if str(get_entity_id(model) or "") == selection_id:
                return model
        return None

