    @staticmethod
    def _sm_effective_cp_cost(player: Any, stratagem: Any, *, target_unit: Any = None) -> int:
        cp_cost = int(getattr(stratagem, "cp_cost", 0) or 0)
        apply_fn = getattr(player, "apply_stratagem_cp_cost", None)
        if callable(apply_fn):
            preview = apply_fn(stratagem, target_unit=target_unit) or {}
            cp_cost = int(preview.get("cost", cp_cost) or cp_cost)
        return int(cp_cost)

    @staticmethod
    def _sm_spend_cp(player: Any, stratagem: Any, *, target_unit: Any = None) -> bool:
        cp_cost = SpaceMarinesStratagemMixin._sm_effective_cp_cost(player, stratagem, target_unit=target_unit)
        return bool(
            player.spend_command_points(
                int(cp_cost),
                reason=f"Stratagem: {getattr(stratagem, 'name', 'Unknown')}",
                source="stratagem",
            )
        )

    def _sm_finalize_use(self, stratagem: Any, *, dequeue: bool = False) -> None:
        if dequeue and hasattr(self, "_dequeue_reaction_by_name"):
            self._dequeue_reaction_by_name(getattr(stratagem, "name", ""))
        used = getattr(self, "_used_stratagems_this_phase", None)
        if isinstance(used, set):
            name_u = str(getattr(stratagem, "name", "") or "").strip().upper()
            if name_u:
                used.add(name_u)

    def _sm_apply_battleshock_if_needed(self, unit: Any) -> None:
        root = self._sm_root(unit)
        if root is None:
            return
        is_battle_shocked = getattr(root, "is_battle_shocked", None)
        if callable(is_battle_shocked) and bool(is_battle_shocked()):
            return
        apply_effect = getattr(root, "apply_status_effect", None)
        if not callable(apply_effect):
            return
        current_turn = int(getattr(self.game, "turn", 0) or 0) if self.game is not None else 0
        apply_effect(BattleShockEffect(current_turn))

    @staticmethod
    def _sm_merge_phase_move_types(
        special_rules: dict[str, Any],
        rule_key: str,
        added_key: str,
        values: set[str],
    ) -> None:
        current = set(special_rules.get(rule_key) or [])
        added = sorted([move_type for move_type in values if move_type not in current])
        merged = sorted(current.union(set(values)))
        if merged:
            special_rules[rule_key] = merged
        else:
            special_rules.pop(rule_key, None)
        if added:
            special_rules[added_key] = added
        else:
            special_rules.pop(added_key, None)

    @staticmethod
    def _sm_remove_phase_move_types(
        special_rules: dict[str, Any],
        rule_key: str,
        added_key: str,
    ) -> None:
        added = set(special_rules.get(added_key) or [])
        if not added:
            return
        current = list(special_rules.get(rule_key) or [])
        kept = [item for item in current if item not in added]
        if kept:
            special_rules[rule_key] = kept
        else:
            special_rules.pop(rule_key, None)
        special_rules.pop(added_key, None)

    def _sm_reaction_already_queued(
        self,
        *,
        event_name: str,
        stratagem_name: str,
        phase_name: str,
        target_unit: Any = None,
        attacking_unit: Any = None,
    ) -> bool:
        for reaction in list(getattr(self, "_pending_reactions", []) or []):
            if str(reaction.get("event", "") or "") != str(event_name):
                continue
            if str(reaction.get("stratagem", "") or "").strip().upper() != str(stratagem_name or "").strip().upper():
                continue
            if str(reaction.get("phase_name", "") or "").strip().lower() != str(phase_name or "").strip().lower():
                continue
            if target_unit is not None and reaction.get("target_unit") is not target_unit and reaction.get("unit") is not target_unit:
                continue
            if attacking_unit is not None and reaction.get("attacking_unit") is not attacking_unit:
                continue
            return True
        return False

    def _sm_game_map(self) -> Any:
        return getattr(self.game, "map", None) if self.game is not None else None

    def _sm_resolve_unit_by_id(self, unit_id: Any) -> Any:
        resolved_id = str(unit_id or "").strip()
        if not resolved_id:
            return None
        resolver = getattr(self.game, "_resolve_unit_by_id", None) if self.game is not None else None
        if callable(resolver):
            resolved = resolver(resolved_id)
            if resolved is not None:
                return resolved
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return None
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            if self._sm_sort_key(root) == resolved_id:
                return root
        return None

    def _sm_owned_army_roots(self) -> list[Any]:
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return []
        roots: list[Any] = []
        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            root_id = self._sm_sort_key(root)
            if root_id and root_id in seen:
                continue
            if root_id:
                seen.add(root_id)
            roots.append(root)
        return sorted(roots, key=self._sm_sort_key)

    def _sm_enemy_army_roots(self) -> list[Any]:
        if self.game is None:
            return []
        roots: list[Any] = []
        seen: set[str] = set()
        for player in list(getattr(self.game, "players", []) or []):
            if player is None or player is self.player:
                continue
            get_army = getattr(player, "get_army", None)
            army = get_army() if callable(get_army) else getattr(player, "army", None)
            if army is None:
                continue
            for unit in list(getattr(army, "units", []) or []):
                root = self._sm_root(unit)
                if root is None:
                    continue
                root_id = self._sm_sort_key(root)
                if root_id and root_id in seen:
                    continue
                if root_id:
                    seen.add(root_id)
                roots.append(root)
        return sorted(roots, key=self._sm_sort_key)

    def _sm_unit_was_set_up_this_turn(self, unit: Any) -> bool:
        root = self._sm_root(unit)
        if root is None:
            return False
        mgr = self._sm_detachment_mgr()
        checker = getattr(mgr, "_attached_unit_was_set_up_this_turn", None) if mgr is not None else None
        if callable(checker):
            return bool(checker(root, game=getattr(self, "game", None)))
        checker = getattr(root, "_was_set_up_this_turn", None)
        if callable(checker):
            try:
                return bool(checker(game=getattr(self, "game", None)))
            except Exception:
                return False
        if bool(getattr(root, "arrived_from_reserves_this_turn", False)):
            return True
        round_state = getattr(root, "round_state", None)
        return bool(getattr(round_state, "reinforced_this_round", False))

    def _sm_objective_candidates_you_control(self, unit: Any) -> list[Any]:
        root = self._sm_root(unit)
        game_map = self._sm_game_map()
        if root is None or game_map is None:
            return []
        is_within = getattr(root, "is_within_objective_range", None)
        if not callable(is_within):
            return []
        out: list[Any] = []
        seen: set[str] = set()
        for objective in list(getattr(game_map, "objectives", []) or []):
            loc = getattr(objective, "location", None)
            if loc is None or bool(getattr(loc, "removed", False)):
                continue
            if not bool(is_within(loc)):
                continue
            controller = getattr(loc, "controlling_player", None)
            sticky_controller = getattr(loc, "sticky_controller", None)
            if controller is not self.player and sticky_controller is not self.player:
                continue
            objective_id = str(getattr(objective, "id", "") or get_entity_id(objective) or "")
            if objective_id and objective_id in seen:
                continue
            if objective_id:
                seen.add(objective_id)
            out.append(objective)
        out.sort(key=lambda objective: str(getattr(objective, "id", "") or get_entity_id(objective) or ""))
        return out

    def _sm_unit_within_any_objective_range(self, unit: Any) -> bool:
        root = self._sm_root(unit)
        game_map = self._sm_game_map()
        if root is None or game_map is None:
            return False
        is_within = getattr(root, "is_within_objective_range", None)
        if not callable(is_within):
            return False
        for objective in list(getattr(game_map, "objectives", []) or []):
            location = getattr(objective, "location", None)
            if location is None or bool(getattr(location, "removed", False)):
                continue
            try:
                if bool(is_within(location)):
                    return True
            except (AttributeError, TypeError, ValueError):
                continue
        return False

