    @staticmethod
    def _sm_hunter_pair_key(first: Any, second: Any) -> str:
        first_id = str(get_entity_id(first) or "")
        second_id = str(get_entity_id(second) or "")
        ids = sorted([item for item in (first_id, second_id) if item])
        return "|".join(ids)

