    @staticmethod
    def _sm_great_wolf_pack_choice_key(choice: Any) -> str:
        if isinstance(choice, dict):
            choice = (
                choice.get("choice_key")
                or choice.get("pack_key")
                or choice.get("pack_name")
                or choice.get("choice")
                or choice.get("label")
            )
        text = str(choice or "").strip().upper()
