    def _cleanup_space_marines_saga_of_the_hunter_phase_end_effects(self, *, phase: Any = None) -> None:
        if not self._is_saga_of_the_hunter_detachment():
            return
        phase_name = str(getattr(phase, "name", "") or "").strip().upper()
        if phase_name not in {"MOVEMENT_PHASE", "SHOOTING_PHASE", "CHARGE_PHASE", "FIGHT_PHASE"}:
            return
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        active_owner_id = str(getattr(active_player, "id", "") or "")
        current_turn = int(getattr(self.game, "turn", 0) or 0) if self.game is not None else 0

        def _iter_unique_roots(roots: list[Any]) -> list[Any]:
            out: list[Any] = []
            seen: set[str] = set()
            for unit in list(roots or []):
                root = self._sm_root(unit)
                if root is None:
                    continue
                root_id = self._sm_sort_key(root)
                if root_id and root_id in seen:
                    continue
                if root_id:
                    seen.add(root_id)
                out.append(root)
            return out

        for root in _iter_unique_roots(self._sm_owned_army_roots()):
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if phase_name in {"MOVEMENT_PHASE", "CHARGE_PHASE"}:
                expires_phase = str(sr.get("space_marines_bounding_advance_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_bounding_advance_active") is True and (not expires_phase or expires_phase == phase_name):
                    self._sm_remove_phase_move_types(
                        sr,
                        "bearer_unit_phase_move_models_only_types",
                        "space_marines_bounding_advance_added_phase_move_models_only_types",
                    )
                    self._sm_remove_phase_move_types(
                        sr,
                        "bearer_unit_phase_move_models_only_block_titanic_types",
                        "space_marines_bounding_advance_added_phase_move_models_only_block_titanic_types",
                    )
                    self._sm_remove_phase_move_types(
                        sr,
                        "bearer_unit_phase_move_engagement_types",
                        "space_marines_bounding_advance_added_phase_move_engagement_types",
                    )
                    for key in (
                        "space_marines_bounding_advance_active",
                        "space_marines_bounding_advance_expires_phase",
                        "space_marines_bounding_advance_turn_owner",
                        "space_marines_bounding_advance_turn",
                        "space_marines_bounding_advance_source",
                        "space_marines_bounding_advance_added_phase_move_models_only_types",
                        "space_marines_bounding_advance_added_phase_move_models_only_block_titanic_types",
                        "space_marines_bounding_advance_added_phase_move_engagement_types",
                    ):
                        sr.pop(key, None)
            if phase_name == "SHOOTING_PHASE":
                expires_phase = str(sr.get("space_marines_marked_for_destruction_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_marked_for_destruction_active") is True and (not expires_phase or expires_phase == phase_name):
                    for key in (
                        "space_marines_marked_for_destruction_active",
                        "space_marines_marked_for_destruction_expires_phase",
                        "space_marines_marked_for_destruction_turn_owner",
                        "space_marines_marked_for_destruction_turn",
                        "space_marines_marked_for_destruction_source",
                        "space_marines_marked_for_destruction_target_id",
                        "space_marines_marked_for_destruction_target_lock",
                        "space_marines_marked_for_destruction_reroll_wound_values",
                    ):
                        sr.pop(key, None)
            if phase_name == "FIGHT_PHASE":
                expires_phase = str(sr.get("space_marines_hunter_hunters_trail_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_hunter_hunters_trail_active") is True and (not expires_phase or expires_phase == phase_name):
                    for key in (
                        "space_marines_hunter_hunters_trail_active",
                        "space_marines_hunter_hunters_trail_expires_phase",
                        "space_marines_hunter_hunters_trail_turn_owner",
                        "space_marines_hunter_hunters_trail_turn",
                        "space_marines_hunter_hunters_trail_source",
                        "stratagem_choreographer_of_war_source",
                        "stratagem_choreographer_of_war_expires_phase",
                        "stratagem_choreographer_of_war_turn_owner",
                        "stratagem_choreographer_of_war_turn",
                    ):
                        sr.pop(key, None)
                    self._sm_clear_ability_cache(root, "choreographer_of_war_source")
                effect_owner = str(sr.get("space_marines_chosen_prey_turn_owner", "") or "").strip()
                try:
                    effect_turn = int(sr.get("space_marines_chosen_prey_turn", 0) or 0)
                except (TypeError, ValueError):
                    effect_turn = 0
                if (
                    sr.get("space_marines_chosen_prey_active") is True
                    and effect_owner
                    and active_owner_id
                    and effect_owner == active_owner_id
                    and (not effect_turn or not current_turn or effect_turn == current_turn)
                ):
                    for key in (
                        "space_marines_chosen_prey_active",
                        "space_marines_chosen_prey_turn_owner",
                        "space_marines_chosen_prey_turn",
                        "space_marines_chosen_prey_source",
                    ):
                        sr.pop(key, None)
            root.special_rules = sr

        if phase_name != "FIGHT_PHASE":
            return
        for root in _iter_unique_roots(self._sm_enemy_army_roots()):
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            expires_phase = str(sr.get("space_marines_overwhelming_onslaught_expires_phase", "") or "").strip().upper()
            if sr.get("space_marines_overwhelming_onslaught_active") is not True or (expires_phase and expires_phase != phase_name):
                continue
            for key in (
                "space_marines_overwhelming_onslaught_active",
                "space_marines_overwhelming_onslaught_expires_phase",
                "space_marines_overwhelming_onslaught_turn_owner",
                "space_marines_overwhelming_onslaught_turn",
                "space_marines_overwhelming_onslaught_source",
                "space_marines_overwhelming_onslaught_hit_modifier",
            ):
                sr.pop(key, None)
            root.special_rules = sr

    def _cleanup_space_marines_saga_of_the_great_wolf_phase_end_effects(self, *, phase: Any = None) -> None:
        if not self._is_saga_of_the_great_wolf_detachment():
            return
        phase_name = str(getattr(phase, "name", "") or "").strip().upper()
        if phase_name not in {"MOVEMENT_PHASE", "CHARGE_PHASE", "FIGHT_PHASE"}:
            return
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        active_owner_id = str(getattr(active_player, "id", "") or "")
        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if phase_name in {"MOVEMENT_PHASE", "CHARGE_PHASE"}:
                exp = str(sr.get("space_marines_fenrisian_ferocity_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_fenrisian_ferocity_active") is True and (not exp or exp == phase_name):
                    self._sm_remove_phase_move_types(
                        sr,
                        "bearer_unit_phase_move_types",
                        "space_marines_fenrisian_ferocity_added_phase_move_types",
                    )
                    self._sm_remove_phase_move_types(
                        sr,
                        "bearer_unit_phase_move_block_titanic_types",
                        "space_marines_fenrisian_ferocity_added_phase_move_block_titanic_types",
                    )
                    self._sm_remove_phase_move_types(
                        sr,
                        "bearer_unit_phase_move_engagement_types",
                        "space_marines_fenrisian_ferocity_added_phase_move_engagement_types",
                    )
                    for key in (
                        "space_marines_fenrisian_ferocity_active",
                        "space_marines_fenrisian_ferocity_expires_phase",
                        "space_marines_fenrisian_ferocity_turn_owner",
                        "space_marines_fenrisian_ferocity_turn",
                        "space_marines_fenrisian_ferocity_source",
                        "space_marines_fenrisian_ferocity_added_phase_move_types",
                        "space_marines_fenrisian_ferocity_added_phase_move_block_titanic_types",
                        "space_marines_fenrisian_ferocity_added_phase_move_engagement_types",
                    ):
                        sr.pop(key, None)
            if phase_name == "FIGHT_PHASE":
                effect_owner = str(sr.get("space_marines_unrelenting_hunters_turn_owner", "") or "").strip()
                if (
                    sr.get("space_marines_unrelenting_hunters_active") is True
                    and effect_owner
                    and active_owner_id
                    and effect_owner == active_owner_id
                ):
                    for key in (
                        "space_marines_unrelenting_hunters_active",
                        "space_marines_unrelenting_hunters_turn_owner",
                        "space_marines_unrelenting_hunters_turn",
                        "space_marines_unrelenting_hunters_source",
                    ):
                        sr.pop(key, None)
            root.special_rules = sr

    @staticmethod
    def _clear_space_marines_beastslayer_impetuosity_pending(root: Any) -> None:
        sr = getattr(root, "special_rules", None)
        if not isinstance(sr, dict):
            return
        for key in (
            "space_marines_beastslayer_impetuosity_pending",
            "space_marines_beastslayer_impetuosity_attacker_id",
            "space_marines_beastslayer_impetuosity_models_before",
            "space_marines_beastslayer_impetuosity_owner",
            "space_marines_beastslayer_impetuosity_turn",
            "space_marines_beastslayer_impetuosity_expires_phase",
            "space_marines_beastslayer_impetuosity_source",
        ):
            sr.pop(key, None)
        root.special_rules = sr

    def _resolve_space_marines_saga_of_the_beastslayer_after_shooting(self, *, attacker_unit: Any) -> None:
        if not self._is_saga_of_the_beastslayer_detachment():
            return
        if str(getattr(self, "_current_phase_name", "") or "").strip().lower() != "shooting phase":
            return
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is self.player:
            return
        attacker_root = self._sm_root(attacker_unit)
        attacker_id = self._sm_sort_key(attacker_root)
        if attacker_root is None or not attacker_id or self._sm_owned_by_player(attacker_root, self.player):
            return
        queue_move = getattr(getattr(self, "game", None), "_queue_reactive_move_movement_decision", None)
        if not callable(queue_move):
            return

        for root in list(self._sm_owned_army_roots() or []):
            if root is None:
                continue
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict) or not bool(sr.get("space_marines_beastslayer_impetuosity_pending")):
                continue
            if str(sr.get("space_marines_beastslayer_impetuosity_attacker_id", "") or "") != attacker_id:
                continue

            try:
                models_before = int(sr.get("space_marines_beastslayer_impetuosity_models_before", 0) or 0)
            except (TypeError, ValueError):
                models_before = 0
            self._clear_space_marines_beastslayer_impetuosity_pending(root)
            if models_before <= 0:
                continue
            if not self._sm_on_battlefield(root, require_targetable=True):
                continue
            if self._sm_alive_model_count(root) >= models_before:
                continue

            max_distance = int(dice_module.get_roll("D6") or 0)
            if max_distance <= 0:
                continue
            request = queue_move(
                player=self.player,
                unit=root,
                max_distance=int(max_distance),
                kind="impetuosity",
                movement_type="bestial_rage",
                reactive_movement_type="bestial_rage",
                source=str(sr.get("space_marines_beastslayer_impetuosity_source", "") or "IMPETUOSITY"),
                attacker_unit=attacker_root,
                allow_engagement_range=True,
                allow_skip=True,
            )
            if request is not None:
                request.context["reactive_move_allow_engagement_range"] = True

    def _cleanup_space_marines_companions_of_vehemence_phase_end_effects(self, *, phase: Any) -> None:
        if not self._is_companions_of_vehemence_detachment():
            return
        phase_key = str(getattr(phase, "name", "") or "").strip().upper()
        if phase_key != "FIGHT_PHASE":
            return
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return
        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if (
                sr.get("space_marines_devout_push_active") is True
                or sr.get("space_marines_hearts_hardened_to_duty_active") is True
                or sr.get("space_marines_pious_enmity_active") is True
            ):
                for key in (
                    "space_marines_devout_push_active",
                    "space_marines_devout_push_expires_phase",
                    "space_marines_devout_push_turn_owner",
                    "space_marines_devout_push_turn",
                    "space_marines_devout_push_source",
                    "space_marines_hearts_hardened_to_duty_active",
                    "space_marines_hearts_hardened_to_duty_expires_phase",
                    "space_marines_hearts_hardened_to_duty_turn_owner",
                    "space_marines_hearts_hardened_to_duty_turn",
                    "space_marines_hearts_hardened_to_duty_source",
                    "space_marines_pious_enmity_active",
                    "space_marines_pious_enmity_expires_phase",
                    "space_marines_pious_enmity_turn_owner",
                    "space_marines_pious_enmity_turn",
                    "space_marines_pious_enmity_source",
                    "stratagem_consolidate_distance_override",
                    "stratagem_consolidate_expires_phase",
                    "stratagem_consolidate_source",
                    "bearer_unit_pile_in_distance_override",
                ):
                    sr.pop(key, None)
                root.special_rules = sr

    def _queue_space_marines_vanguard_phase_start_reactions(self, *, player: Any, phase: Any) -> None:
        if not self._is_vanguard_spearhead_detachment():
            return
        phase_key = str(getattr(phase, "name", "") or "").strip().upper()
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None

        if phase_key == "COMMAND_PHASE":
            stratagem = self.get_by_name("A DEADLY PRIZE")
            candidates, objective_map = self._space_marines_vanguard_deadly_prize_candidates()
            if stratagem is not None and candidates:
                if (
                    int(getattr(self.player, "command_points", 0) or 0) >= self._sm_effective_cp_cost(self.player, stratagem)
                    and str(stratagem.name or "").strip().upper() not in self._used_stratagems_this_phase
                    and not self._sm_reaction_already_queued(
                        event_name="phase_start",
                        stratagem_name=stratagem.name,
                        phase_name="Command phase",
                    )
                ):
                    payload: dict[str, Any] = {
                        "event": "phase_start",
                        "phase": "Command phase",
                        "phase_name": "Command phase",
                        "stratagem": stratagem.name,
                        "cp_cost": stratagem.cp_cost,
                        "candidates": candidates,
                        "objective_candidates_by_unit": objective_map,
                    }
                    if len(candidates) == 1:
                        payload["unit"] = candidates[0]
                        payload["target_unit"] = candidates[0]
                        objective_candidates = list(objective_map.get(self._sm_sort_key(candidates[0])) or [])
                        if objective_candidates:
                            payload["objective_candidates"] = objective_candidates
                            if len(objective_candidates) == 1:
                                payload["objective"] = objective_candidates[0]
                                payload["objective_marker"] = objective_candidates[0]
                    self._queue_reaction(payload, use_timer=False)

        if phase_key == "SHOOTING_PHASE" and player is self.player and active_player is self.player:
            stratagem = self.get_by_name("STRIKE FROM THE SHADOWS")
            candidates = self._space_marines_vanguard_infantry_phase_candidates(phase_name="Shooting phase")
            if stratagem is not None and candidates:
                if (
                    int(getattr(self.player, "command_points", 0) or 0) >= self._sm_effective_cp_cost(self.player, stratagem)
                    and str(stratagem.name or "").strip().upper() not in self._used_stratagems_this_phase
                    and not self._sm_reaction_already_queued(
                        event_name="phase_start",
                        stratagem_name=stratagem.name,
                        phase_name="Shooting phase",
                    )
                ):
                    payload = {
                        "event": "phase_start",
                        "phase": "Shooting phase",
                        "phase_name": "Shooting phase",
                        "stratagem": stratagem.name,
                        "cp_cost": stratagem.cp_cost,
                        "candidates": candidates,
                    }
                    if len(candidates) == 1:
                        payload["unit"] = candidates[0]
                        payload["target_unit"] = candidates[0]
                    self._queue_reaction(payload, use_timer=False)

        if phase_key == "FIGHT_PHASE":
            stratagem = self.get_by_name("SURGICAL STRIKES")
            candidates = self._space_marines_vanguard_infantry_phase_candidates(phase_name="Fight phase")
            if stratagem is not None and candidates:
                if (
                    int(getattr(self.player, "command_points", 0) or 0) >= self._sm_effective_cp_cost(self.player, stratagem)
                    and str(stratagem.name or "").strip().upper() not in self._used_stratagems_this_phase
                    and not self._sm_reaction_already_queued(
                        event_name="phase_start",
                        stratagem_name=stratagem.name,
                        phase_name="Fight phase",
                    )
                ):
                    payload = {
                        "event": "phase_start",
                        "phase": "Fight phase",
                        "phase_name": "Fight phase",
                        "stratagem": stratagem.name,
                        "cp_cost": stratagem.cp_cost,
                        "candidates": candidates,
                    }
                    if len(candidates) == 1:
                        payload["unit"] = candidates[0]
                        payload["target_unit"] = candidates[0]
                    self._queue_reaction(payload, use_timer=False)

