    def _resolve_space_marines_vindication_phase_end_effects(self, *, phase: Any) -> None:
        if not self._is_vindication_task_force_detachment():
            return
        phase_key = str(getattr(phase, "name", "") or "").strip().upper()
        if not phase_key:
            return

        pending = self._space_marines_vindication_refusal_to_yield_pending_returns()
        game = getattr(self, "game", None)
        current_turn = int(getattr(game, "turn", 0) or 0) if game is not None else 0
        current_player = getattr(game, "get_current_player", lambda: None)() if game is not None else None
        current_player_id = str(getattr(current_player, "id", "") or "")
        game_map = getattr(game, "map", None) if game is not None else None
        find_pos = getattr(game, "_find_closest_valid_reposition_position", None) if game is not None else None

        remaining: list[dict[str, Any]] = []
        for entry in list(pending):
            if not isinstance(entry, dict):
                continue
            trigger_phase_key = self._phase_key_from_name(
                str(entry.get("trigger_phase_key") or entry.get("trigger_phase_name") or "")
            )
            if trigger_phase_key and trigger_phase_key != phase_key:
                remaining.append(entry)
                continue
            try:
                trigger_turn = int(entry.get("trigger_turn", 0) or 0)
            except (TypeError, ValueError):
                trigger_turn = 0
            if trigger_turn and current_turn and trigger_turn != current_turn:
                remaining.append(entry)
                continue
            trigger_player_id = str(entry.get("trigger_player_id", "") or "")
            if trigger_player_id and current_player_id and trigger_player_id != current_player_id:
                remaining.append(entry)
                continue

            root = self._sm_root(entry.get("unit"))
            model = entry.get("model")
            if root is None or model is None:
                continue

            in_unit = False
            try:
                in_unit = model in list(getattr(root, "models", []) or [])
            except (AttributeError, TypeError, ValueError):
                in_unit = False
            if not in_unit:
                try:
                    if model in list(getattr(root, "models_lost", []) or []):
                        root.models_lost.remove(model)
                except (AttributeError, TypeError, ValueError):
                    pass
                add_model = getattr(root, "add_model", None)
                if callable(add_model):
                    try:
                        add_model(model)
                    except (AttributeError, TypeError, ValueError):
                        try:
                            root.models.append(model)
                        except (AttributeError, TypeError, ValueError):
                            pass
                else:
                    try:
                        root.models.append(model)
                    except (AttributeError, TypeError, ValueError):
                        pass

            try:
                starting_wounds = int(
                    getattr(
                        model,
                        "_base_wounds",
                        getattr(model, "base_wounds", getattr(model, "wounds", getattr(model, "_wounds", 1))),
                    )
                    or 1
                )
            except (AttributeError, TypeError, ValueError):
                starting_wounds = 1
            wounds_remaining = max(1, int(starting_wounds))
            try:
                model.wounds = int(wounds_remaining)
            except (AttributeError, TypeError, ValueError):
                try:
                    model._wounds = int(wounds_remaining)
                except (AttributeError, TypeError, ValueError):
                    pass

            for key, value in (
                ("_on_death_reactions_resolved", False),
                ("_fight_on_death_used", False),
                ("_shoot_on_death_used", False),
            ):
                try:
                    setattr(model, key, value)
                except (AttributeError, TypeError, ValueError):
                    pass

            anchor = entry.get("destroyed_position")
            if anchor is None:
                get_location = getattr(model, "get_location", None)
                if callable(get_location):
                    try:
                        anchor = get_location()
                    except (AttributeError, TypeError, ValueError):
                        anchor = None
            placement = None
            if callable(find_pos) and isinstance(anchor, (list, tuple)) and len(anchor) >= 3:
                try:
                    placement = find_pos(root, anchor, game_map=game_map)
                except (AttributeError, TypeError, ValueError):
                    placement = None
            if placement is None and isinstance(anchor, (list, tuple)) and len(anchor) >= 4:
                try:
                    placement = (float(anchor[0]), float(anchor[1]), float(anchor[2]), float(anchor[3]))
                except (TypeError, ValueError):
                    placement = None
            if placement is not None:
                try:
                    model.set_location(
                        float(placement[0]),
                        float(placement[1]),
                        float(placement[2]),
                        float(placement[3]),
                    )
                except (AttributeError, TypeError, ValueError):
                    pass

            root.deployed = True
            try:
                root.reserve_status = "deployed"
            except (AttributeError, TypeError, ValueError):
                pass
            try:
                root.embarked_in = None
            except (AttributeError, TypeError, ValueError):
                pass
            try:
                root.is_embarked = False
            except (AttributeError, TypeError, ValueError):
                pass

            if game_map is not None:
                units = list(getattr(game_map, "units", []) or [])
                if root not in units:
                    place_unit = getattr(game_map, "place_unit", None)
                    if callable(place_unit):
                        try:
                            placed = bool(place_unit(root))
                        except (AttributeError, TypeError, ValueError):
                            placed = False
                        if not placed and isinstance(getattr(game_map, "units", None), list):
                            game_map.units.append(root)
                    elif isinstance(getattr(game_map, "units", None), list):
                        game_map.units.append(root)
            logger.info(
                "INFO: REFUSAL TO YIELD: returned %s with %d wound(s).",
                getattr(model, "name", "Model"),
                int(wounds_remaining),
            )
        setattr(self, "_space_marines_vindication_refusal_to_yield_pending", remaining)

        if phase_key not in {"SHOOTING_PHASE", "FIGHT_PHASE"}:
            return
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return
        mgr = self._sm_detachment_mgr()
        clear_spoor = getattr(mgr, "clear_vindication_spoor_of_the_unholy", None) if mgr is not None else None
        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            sr = getattr(root, "special_rules", None)
            if isinstance(sr, dict) and bool(sr.get("space_marines_vindication_spoor_of_the_unholy_active")):
                exp = str(sr.get("space_marines_vindication_spoor_of_the_unholy_expires_phase", "") or "").strip().upper()
                if not exp or exp == phase_key:
                    if callable(clear_spoor):
                        clear_spoor(root)
            for model in self._sm_unit_models(root):
                effects = getattr(model, "_temporary_effects", None)
                if not isinstance(effects, dict) or not effects:
                    continue
                remove_keys: list[str] = []
                for key, value in list(effects.items()):
                    key_text = str(key or "")
                    if not key_text.startswith("space_marines_vindication_spoor_of_the_unholy:"):
                        continue
                    exp = str(value.get("expires_phase", "") or "").strip().upper() if isinstance(value, dict) else ""
                    if not exp or exp == phase_key:
                        remove_keys.append(str(key))
                for key in remove_keys:
                    effects.pop(key, None)

    def _cleanup_space_marines_saga_of_the_beastslayer_phase_end_effects(self, *, phase: Any = None) -> None:
        phase_name = str(getattr(phase, "name", "") or "").strip().upper()
        if not phase_name:
            return
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return

        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            models = []
            get_models = getattr(root, "get_attached_unit_models", None)
            if callable(get_models):
                models = list(get_models() or [])
            if not models:
                models = list(getattr(root, "models", []) or [])
            for model in models:
                effects = getattr(model, "_temporary_effects", None)
                if not isinstance(effects, dict) or not effects:
                    continue
                remove_keys: list[str] = []
                for key, value in list(effects.items()):
                    key_text = str(key or "")
                    if not (
                        key_text.startswith("angelic_grace:")
                        or key_text.startswith("fuelled_by_faith:")
                        or key_text.startswith("watcher_in_the_dark:")
                    ):
                        continue
                    exp_phase = str(value.get("expires_phase", "") or "").strip().upper() if isinstance(value, dict) else ""
                    if not exp_phase or exp_phase == phase_name:
                        remove_keys.append(str(key))
                for key in remove_keys:
                    effects.pop(key, None)

        if phase_name in ("SHOOTING_PHASE", "FIGHT_PHASE"):
            seen = set()
            for unit in list(getattr(army, "units", []) or []):
                root = self._sm_root(unit)
                if root is None:
                    continue
                uid = self._sm_sort_key(root)
                if uid and uid in seen:
                    continue
                if uid:
                    seen.add(uid)
                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                if phase_name == "FIGHT_PHASE":
                    exp = str(sr.get("space_marines_litanies_of_purgation_expires_phase", "") or "").strip().upper()
                    if sr.get("space_marines_litanies_of_purgation_active") is True and (not exp or exp == phase_name):
                        for key in (
                            "space_marines_litanies_of_purgation_active",
                            "space_marines_litanies_of_purgation_ap_bonus",
                            "space_marines_litanies_of_purgation_expires_phase",
                            "space_marines_litanies_of_purgation_turn_owner",
                            "space_marines_litanies_of_purgation_turn",
                            "space_marines_litanies_of_purgation_source",
                        ):
                            sr.pop(key, None)
                exp = str(sr.get("space_marines_heroes_of_the_chapter_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_heroes_of_the_chapter_active") is True and (not exp or exp == phase_name):
                    for key in (
                        "space_marines_heroes_of_the_chapter_active",
                        "space_marines_heroes_of_the_chapter_hit_bonus",
                        "space_marines_heroes_of_the_chapter_wound_bonus",
                        "space_marines_heroes_of_the_chapter_wound_bonus_below_half_only",
                        "space_marines_heroes_of_the_chapter_wound_bonus_below_starting_only",
                        "space_marines_heroes_of_the_chapter_expires_phase",
                        "space_marines_heroes_of_the_chapter_turn_owner",
                        "space_marines_heroes_of_the_chapter_turn",
                        "space_marines_heroes_of_the_chapter_source",
                    ):
                        sr.pop(key, None)
                if phase_name == "SHOOTING_PHASE":
                    exp = str(sr.get("space_marines_in_the_shadow_expires_phase", "") or "").strip().upper()
                    if sr.get("space_marines_in_the_shadow_active") is True and (not exp or exp == phase_name):
                        for key in (
                            "space_marines_in_the_shadow_active",
                            "space_marines_in_the_shadow_targeting_range",
                            "space_marines_in_the_shadow_expires_phase",
                            "space_marines_in_the_shadow_turn_owner",
                            "space_marines_in_the_shadow_turn",
                            "space_marines_in_the_shadow_source",
                        ):
                            sr.pop(key, None)
                root.special_rules = sr

        if not self._is_saga_of_the_beastslayer_detachment():
            return
        if phase_name not in ("MOVEMENT_PHASE", "CHARGE_PHASE", "SHOOTING_PHASE"):
            return

        seen = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if phase_name in ("MOVEMENT_PHASE", "CHARGE_PHASE"):
                exp = str(sr.get("space_marines_shock_cavalry_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_shock_cavalry_active") is True and (not exp or exp == phase_name):
                    for key, added_key in (
                        (
                            "bearer_unit_phase_move_models_only_types",
                            "space_marines_shock_cavalry_added_phase_move_models_only_types",
                        ),
                        (
                            "bearer_unit_phase_move_models_only_block_titanic_types",
                            "space_marines_shock_cavalry_added_phase_move_models_only_block_titanic_types",
                        ),
                        (
                            "move_over_low_terrain_height_types",
                            "space_marines_shock_cavalry_added_low_terrain_types",
                        ),
                        (
                            "bearer_unit_phase_move_engagement_types",
                            "space_marines_shock_cavalry_added_phase_move_engagement_types",
                        ),
                    ):
                        added = set(sr.get(added_key) or [])
                        if not added:
                            continue
                        current = list(sr.get(key) or [])
                        kept = [item for item in current if item not in added]
                        if kept:
                            sr[key] = kept
                        else:
                            sr.pop(key, None)

                    if bool(sr.get("space_marines_shock_cavalry_prev_low_terrain_height_present", False)):
                        sr["move_over_low_terrain_height_value"] = float(
                            sr.get("space_marines_shock_cavalry_prev_low_terrain_height_value", 4.0) or 4.0
                        )
                    else:
                        sr.pop("move_over_low_terrain_height_value", None)

                    for key in (
                        "space_marines_shock_cavalry_active",
                        "space_marines_shock_cavalry_expires_phase",
                        "space_marines_shock_cavalry_turn_owner",
                        "space_marines_shock_cavalry_turn",
                        "space_marines_shock_cavalry_source",
                        "space_marines_shock_cavalry_added_phase_move_models_only_types",
                        "space_marines_shock_cavalry_added_phase_move_models_only_block_titanic_types",
                        "space_marines_shock_cavalry_added_low_terrain_types",
                        "space_marines_shock_cavalry_added_phase_move_engagement_types",
                        "space_marines_shock_cavalry_prev_low_terrain_height_present",
                        "space_marines_shock_cavalry_prev_low_terrain_height_value",
                    ):
                        sr.pop(key, None)

            if phase_name == "SHOOTING_PHASE":
                exp = str(sr.get("space_marines_pinning_fire_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_pinning_fire_active") is True and (not exp or exp == phase_name):
                    for key in (
                        "space_marines_pinning_fire_active",
                        "space_marines_pinning_fire_source",
                        "space_marines_pinning_fire_move_penalty",
                        "space_marines_pinning_fire_charge_penalty",
                        "space_marines_pinning_fire_target_keywords_any",
                        "space_marines_pinning_fire_pinned_expires_phase",
                        "space_marines_pinning_fire_expires_phase",
                        "space_marines_pinning_fire_turn_owner",
                        "space_marines_pinning_fire_turn",
                    ):
                        sr.pop(key, None)
                    self._sm_clear_ability_cache(root, "unit_post_shoot_pinned_specs")
                exp = str(sr.get("space_marines_beastslayer_impetuosity_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_beastslayer_impetuosity_pending") is True and (not exp or exp == phase_name):
                    self._clear_space_marines_beastslayer_impetuosity_pending(root)
            root.special_rules = sr

    def _cleanup_space_marines_saga_of_the_bold_phase_end_effects(self, *, phase: Any = None) -> None:
        if not self._is_saga_of_the_bold_detachment():
            return
        phase_name = str(getattr(phase, "name", "") or "").strip().upper()
        if phase_name not in {"CHARGE_PHASE", "SHOOTING_PHASE", "FIGHT_PHASE"}:
            return
        get_army = getattr(self.player, "get_army", None)
        army = get_army() if callable(get_army) else getattr(self.player, "army", None)
        if army is None:
            return
        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            root = self._sm_root(unit)
            if root is None:
                continue
            uid = self._sm_sort_key(root)
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if phase_name == "CHARGE_PHASE":
                exp = str(sr.get("space_marines_alpha_strike_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_alpha_strike_active") is True and (not exp or exp == phase_name):
                    for key in (
                        "space_marines_alpha_strike_active",
                        "space_marines_alpha_strike_expires_phase",
                        "space_marines_alpha_strike_turn_owner",
                        "space_marines_alpha_strike_turn",
                        "space_marines_alpha_strike_source",
                    ):
                        sr.pop(key, None)
            if phase_name in {"SHOOTING_PHASE", "FIGHT_PHASE"}:
                exp = str(sr.get("space_marines_champions_guidance_expires_phase", "") or "").strip().upper()
                if sr.get("space_marines_champions_guidance_active") is True and (not exp or exp == phase_name):
                    for key in (
                        "space_marines_champions_guidance_active",
                        "space_marines_champions_guidance_expires_phase",
                        "space_marines_champions_guidance_turn_owner",
                        "space_marines_champions_guidance_turn",
                        "space_marines_champions_guidance_source",
                    ):
                        sr.pop(key, None)
            root.special_rules = sr

    def _queue_space_marines_mortal_wound_reactions(
        self,
        *,
        target_unit: Any,
        attacker_unit: Any = None,
        target_model: Any = None,
        phase_name: str = "",
    ) -> None:
        root = self._sm_root(target_unit)
        if root is None:
            return
        if not self._sm_owned_by_player(root, self.player):
            return
        if not self._sm_on_battlefield(root, require_targetable=True):
            return
        if not self._is_adeptus_astartes_unit(root):
            return

        if not phase_name:
            phase_name = str(getattr(self, "_current_phase_name", "") or "")
        if not phase_name:
            phase_key = str(getattr(getattr(self.game, "phase", None), "name", "") or "").strip().upper()
            name_map = {
                "COMMAND_PHASE": "Command phase",
                "MOVEMENT_PHASE": "Movement phase",
                "SHOOTING_PHASE": "Shooting phase",
                "CHARGE_PHASE": "Charge phase",
                "FIGHT_PHASE": "Fight phase",
            }
            phase_name = name_map.get(phase_key, phase_key.title().replace("_", " ")) if phase_key else ""
        if not phase_name:
            phase_name = "Any phase"

        for stratagem_name in ("ANGELIC GRACE", "FUELLED BY FAITH"):
            stratagem = self.get_by_name(stratagem_name)
            if stratagem is None:
                continue
            if int(getattr(self.player, "command_points", 0) or 0) < self._sm_effective_cp_cost(self.player, stratagem, target_unit=root):
                continue
            if str(stratagem.name or "").strip().upper() in set(getattr(self, "_used_stratagems_this_phase", set()) or set()):
                continue
            if self._sm_reaction_already_queued(
                event_name="mortal_wound_allocated",
                stratagem_name=stratagem.name,
                phase_name=phase_name,
                target_unit=root,
            ):
                continue
            self._queue_reaction(
                {
                    "event": "mortal_wound_allocated",
                    "phase_name": phase_name,
                    "stratagem": stratagem.name,
                    "cp_cost": stratagem.cp_cost,
                    "target_unit": root,
                    "unit": root,
                    "attacking_unit": attacker_unit,
                    "target_model": target_model,
                    "candidates": [root],
                    "mortal_wound_allocated": True,
                },
                use_timer=False,
            )

    def _use_space_marines_mortal_wound_stratagem(self, stratagem: Any, **kwargs) -> bool:
        unit = kwargs.get("unit") or kwargs.get("target_unit")
        candidates = list(kwargs.get("candidates") or [])
        from_pending = False
        if unit is None:
            for reaction in reversed(list(getattr(self, "_pending_reactions", []) or [])):
                if str(reaction.get("stratagem", "") or "").strip().upper() != str(getattr(stratagem, "name", "") or "").strip().upper():
                    continue
                from_pending = True
                unit = reaction.get("unit") or reaction.get("target_unit")
                if not candidates:
                    candidates = list(reaction.get("candidates") or [])
                if not kwargs.get("phase_name"):
                    kwargs["phase_name"] = reaction.get("phase_name")
                kwargs.setdefault("mortal_wound_allocated", reaction.get("mortal_wound_allocated"))
                break
        if unit is None and len(candidates) == 1:
            unit = candidates[0]
        if unit is None:
            logger.error("ERROR: %s: no target unit provided", getattr(stratagem, "name", "Space Marines stratagem"))
            return False

        root = self._sm_root(unit)
        if root is None:
            return False
        if not from_pending:
            for reaction in reversed(list(getattr(self, "_pending_reactions", []) or [])):
                if str(reaction.get("stratagem", "") or "").strip().upper() != str(getattr(stratagem, "name", "") or "").strip().upper():
                    continue
                pending_root = self._sm_root(reaction.get("unit") or reaction.get("target_unit"))
                if pending_root is not root:
                    continue
                from_pending = True
                if not kwargs.get("phase_name"):
                    kwargs["phase_name"] = reaction.get("phase_name")
                kwargs.setdefault("mortal_wound_allocated", reaction.get("mortal_wound_allocated"))
                break
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: %s: target unit is not yours", getattr(stratagem, "name", "Space Marines stratagem"))
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: %s: target must be on the battlefield and targetable", getattr(stratagem, "name", "Space Marines stratagem"))
            return False
        if candidates and root not in candidates:
            logger.error("ERROR: %s: selected unit is not currently eligible", getattr(stratagem, "name", "Space Marines stratagem"))
            return False
        if not self._is_adeptus_astartes_unit(root):
            logger.error("ERROR: %s: target must be an ADEPTUS ASTARTES unit", getattr(stratagem, "name", "Space Marines stratagem"))
            return False

        trigger_flag = bool(kwargs.get("mortal_wound_allocated", False))
        trigger_name = str(kwargs.get("trigger", "") or "").strip().lower()
        if not from_pending and not trigger_flag and trigger_name not in {"mortal_wound_allocated", "mortal_wound"}:
            logger.error("ERROR: %s: missing mortal-wound trigger context", getattr(stratagem, "name", "Space Marines stratagem"))
            return False

        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False

        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "")
        phase_key = self._phase_key_from_name(phase_name) if phase_name else ""
        models = []
        get_models = getattr(root, "get_attached_unit_models", None)
        if callable(get_models):
            models = list(get_models() or [])
        if not models:
            models = list(getattr(root, "models", []) or [])
        key_seed = self._normalize_stratagem_name(getattr(stratagem, "name", "") or "").lower().replace(" ", "_")
        for index, model in enumerate(models):
            is_alive_attr = getattr(model, "is_alive", True)
            is_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
            if not is_alive:
                continue
            key = f"{key_seed}:{get_entity_id(model) or index}"
            set_temporary_fnp = getattr(model, "set_temporary_fnp", None)
            if callable(set_temporary_fnp):
                set_temporary_fnp(
                    key=key,
                    value=5,
                    source=str(getattr(stratagem, "name", "") or "Space Marines mortal-wound stratagem"),
                    condition="against mortal wounds",
                    expires_phase=phase_key,
                )
                continue
            effects = getattr(model, "_temporary_effects", None)
            if not isinstance(effects, dict):
                effects = {}
                model._temporary_effects = effects
            effects[key] = {
                "expires_phase": str(phase_key or "").strip().upper(),
                "temporary_fnp_value": 5,
                "temporary_fnp_source": str(getattr(stratagem, "name", "") or "Space Marines mortal-wound stratagem"),
                "temporary_fnp_condition": "against mortal wounds",
            }

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: %s: %s gains FNP 5+ against mortal wounds this phase.",
            getattr(stratagem, "name", "Space Marines mortal-wound stratagem"),
            getattr(root, "name", "Unit"),
        )
        return True

    def _use_space_marines_gauntlet_of_the_god_emperor(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "movement phase":
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is not self.player:
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: not your Movement phase")
            return False

        unit, candidates, _trigger_unit, _target_units, _from_pending = self._sm_godhammer_context(
            "GAUNTLET OF THE GOD-EMPEROR",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: no target unit provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: target model is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root) or not self._sm_is_vehicle_unit(root):
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: target must be an ADEPTUS ASTARTES VEHICLE")
            return False
        if self._sm_selected_to_move_this_phase(root):
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: target has already been selected to move this phase")
            return False
        eligible = candidates or self._space_marines_godhammer_phase_unit_candidates(
            phase_name="Movement phase",
            require_vehicle=True,
            require_not_selected_to_move=True,
        )
        if eligible and not self._sm_unit_in_candidates(root, eligible):
            logger.error("ERROR: GAUNTLET OF THE GOD-EMPEROR: selected model is not currently eligible")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False

        sr = getattr(root, "special_rules", None)
        if not isinstance(sr, dict):
            sr = {}
        self._sm_merge_phase_move_types(
            sr,
            "bearer_unit_phase_move_terrain_only_types",
            "space_marines_gauntlet_of_the_god_emperor_added_phase_move_terrain_only_types",
            {"move", "advance"},
        )
        sr["space_marines_gauntlet_of_the_god_emperor_active"] = True
        sr["space_marines_gauntlet_of_the_god_emperor_expires_phase"] = "MOVEMENT_PHASE"
        sr["space_marines_gauntlet_of_the_god_emperor_source"] = str(
            getattr(stratagem, "name", "") or "GAUNTLET OF THE GOD-EMPEROR"
        )
        owner_id = str(getattr(self.player, "id", "") or "")
        if owner_id:
            sr["space_marines_gauntlet_of_the_god_emperor_turn_owner"] = owner_id
        turn = int(getattr(self.game, "turn", 0) or 0) if self.game is not None else 0
        if turn:
            sr["space_marines_gauntlet_of_the_god_emperor_turn"] = turn
        root.special_rules = sr

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: GAUNTLET OF THE GOD-EMPEROR: %s can move horizontally through terrain on Normal and Advance moves this phase.",
            getattr(root, "name", "Unit"),
        )
        return True

    def _use_space_marines_uncompromising_egress(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "movement phase":
            logger.error("ERROR: UNCOMPROMISING EGRESS: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is not self.player:
            logger.error("ERROR: UNCOMPROMISING EGRESS: not your Movement phase")
            return False

        unit, candidates, _trigger_unit, _target_units, _from_pending = self._sm_godhammer_context(
            "UNCOMPROMISING EGRESS",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: UNCOMPROMISING EGRESS: no target transport provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: UNCOMPROMISING EGRESS: target transport is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: UNCOMPROMISING EGRESS: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root) or not self._sm_is_land_raider_unit(root):
            logger.error("ERROR: UNCOMPROMISING EGRESS: target must be an ADEPTUS ASTARTES LAND RAIDER")
            return False
        if self._sm_selected_to_move_this_phase(root):
            logger.error("ERROR: UNCOMPROMISING EGRESS: target has already been selected to move this phase")
            return False
        eligible = candidates or self._space_marines_godhammer_phase_unit_candidates(
            phase_name="Movement phase",
            require_land_raider=True,
            require_transport_passengers=True,
            require_not_selected_to_move=True,
        )
        if eligible and not self._sm_unit_in_candidates(root, eligible):
            logger.error("ERROR: UNCOMPROMISING EGRESS: selected transport is not currently eligible")
            return False
        embarked = [
            passenger
            for passenger in list(getattr(root, "transport_passengers", []) or [])
            if self._is_adeptus_astartes_unit(passenger)
        ]
        if not embarked:
            logger.error("ERROR: UNCOMPROMISING EGRESS: no embarked ADEPTUS ASTARTES units")
            return False
        queue_fn = getattr(self.game, "_queue_transport_reactive_disembark_decisions", None) if self.game is not None else None
        if not callable(queue_fn):
            logger.error("ERROR: UNCOMPROMISING EGRESS: reactive disembark decision queue unavailable")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False
        requests = list(
            queue_fn(
                player=self.player,
                transport=root,
                ability={"name": str(getattr(stratagem, "name", "") or "UNCOMPROMISING EGRESS"), "range": 6},
                trigger="phase_start",
                max_units=1,
                disembark_max_distance=6.0,
                disembark_require_not_in_engagement=False,
            )
            or []
        )
        if not requests:
            logger.error("ERROR: UNCOMPROMISING EGRESS: no disembark decision was queued")
            return False
        allowed_ids = {self._sm_sort_key(passenger) for passenger in embarked}
        for request in requests:
            filtered = []
            for option in list(getattr(request, "options", []) or []):
                payload = dict(getattr(option, "payload", {}) or {})
                unit_id = str(payload.get("unit_id", "") or "")
                if bool(payload.get("skip", False)) or str(payload.get("action", "") or "").strip().lower() == "skip":
                    filtered.append(option)
                    continue
                if unit_id and unit_id in allowed_ids:
                    filtered.append(option)
            request.options = filtered
            request.candidates = []
            request.mask = []
            request.mask_reasons = []
            request.finalize_candidates()

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: UNCOMPROMISING EGRESS: %s can disembark one embarked unit wholly within 6\", including into Engagement Range.",
            getattr(root, "name", "Transport"),
        )
        return True

    def _use_space_marines_condemnatory_info_screed(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "fight phase":
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is not self.player:
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: not your Fight phase")
            return False

        unit, candidates, _trigger_unit, _target_units, _from_pending = self._sm_godhammer_context(
            "CONDEMNATORY INFO-SCREED",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: no target unit provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: target unit is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root):
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: target must be an ADEPTUS ASTARTES unit")
            return False
        if self._sm_selected_to_fight_this_phase(root):
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: target has already been selected to fight this phase")
            return False
        eligible = candidates or self._space_marines_godhammer_phase_unit_candidates(
            phase_name="Fight phase",
            require_not_selected_to_fight=True,
        )
        if eligible and not self._sm_unit_in_candidates(root, eligible):
            logger.error("ERROR: CONDEMNATORY INFO-SCREED: selected unit is not currently eligible")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False

        transport_id = str(getattr(getattr(root, "round_state", None), "disembarked_from_transport_id", "") or "").strip()
        if transport_id:
            transport = self._sm_resolve_unit_by_id(transport_id)
            mode = "full" if self._sm_is_land_raider_unit(transport) else "ones"
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                sr = {}
            sr["space_marines_condemnatory_info_screed_active"] = True
            sr["space_marines_condemnatory_info_screed_expires_phase"] = "FIGHT_PHASE"
            sr["space_marines_condemnatory_info_screed_mode"] = mode
            sr["space_marines_condemnatory_info_screed_transport_id"] = transport_id
            sr["space_marines_condemnatory_info_screed_source"] = str(
                getattr(stratagem, "name", "") or "CONDEMNATORY INFO-SCREED"
            )
            owner_id = str(getattr(self.player, "id", "") or "")
            if owner_id:
                sr["space_marines_condemnatory_info_screed_turn_owner"] = owner_id
            turn = int(getattr(self.game, "turn", 0) or 0) if self.game is not None else 0
            if turn:
                sr["space_marines_condemnatory_info_screed_turn"] = turn
            root.special_rules = sr

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        if transport_id:
            logger.info(
                "INFO: CONDEMNATORY INFO-SCREED: %s gains %s wound re-rolls this phase.",
                getattr(root, "name", "Unit"),
                "full" if sr.get("space_marines_condemnatory_info_screed_mode") == "full" else "1s",
            )
        else:
            logger.info(
                "INFO: CONDEMNATORY INFO-SCREED: %s was not disembarked from a Transport this turn, so the stratagem has no attack modifier to apply.",
                getattr(root, "name", "Unit"),
            )
        return True

    def _use_space_marines_focused_hatred(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "charge phase":
            logger.error("ERROR: FOCUSED HATRED: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is not self.player:
            logger.error("ERROR: FOCUSED HATRED: not your Charge phase")
            return False

        unit, candidates, trigger_unit, target_units, _from_pending = self._sm_godhammer_context(
            "FOCUSED HATRED",
            kwargs,
        )
        if unit is None:
            unit = trigger_unit
        if unit is None:
            logger.error("ERROR: FOCUSED HATRED: no target unit provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: FOCUSED HATRED: target unit is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: FOCUSED HATRED: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root):
            logger.error("ERROR: FOCUSED HATRED: target must be an ADEPTUS ASTARTES unit")
            return False
        transport_id = str(getattr(getattr(root, "round_state", None), "disembarked_from_transport_id", "") or "").strip()
        if not transport_id:
            logger.error("ERROR: FOCUSED HATRED: target must have disembarked from a Transport this turn")
            return False
        charge_target_ids = set(getattr(getattr(root, "round_state", None), "charge_target_ids", None) or set())
        if not charge_target_ids and not list(target_units or []):
            logger.error("ERROR: FOCUSED HATRED: target must have just made a Charge roll")
            return False
        if candidates and not self._sm_unit_in_candidates(root, candidates):
            logger.error("ERROR: FOCUSED HATRED: selected unit is not currently eligible")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False

        sr = getattr(root, "special_rules", None)
        if not isinstance(sr, dict):
            sr = {}
        self._sm_merge_phase_move_types(
            sr,
            "bearer_unit_phase_move_models_only_types",
            "space_marines_focused_hatred_added_phase_move_models_only_types",
            {"charge"},
        )
        sr["space_marines_focused_hatred_active"] = True
        sr["space_marines_focused_hatred_expires_phase"] = "CHARGE_PHASE"
        sr["space_marines_focused_hatred_source"] = str(getattr(stratagem, "name", "") or "FOCUSED HATRED")
        owner_id = str(getattr(self.player, "id", "") or "")
        if owner_id:
            sr["space_marines_focused_hatred_turn_owner"] = owner_id
        turn = int(getattr(self.game, "turn", 0) or 0) if self.game is not None else 0
        if turn:
            sr["space_marines_focused_hatred_turn"] = turn
        root.special_rules = sr

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: FOCUSED HATRED: %s can move through models while making a Charge move this phase.",
            getattr(root, "name", "Unit"),
        )
        return True

    def _use_space_marines_a_ceaseless_cause(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "fight phase":
            logger.error("ERROR: A CEASELESS CAUSE: wrong phase")
            return False

        unit, candidates, _trigger_unit, _target_units, _from_pending = self._sm_godhammer_context(
            "A CEASELESS CAUSE",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: A CEASELESS CAUSE: no target unit provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: A CEASELESS CAUSE: target unit is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: A CEASELESS CAUSE: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root) or not self._sm_is_infantry_unit(root):
            logger.error("ERROR: A CEASELESS CAUSE: target must be an ADEPTUS ASTARTES INFANTRY unit")
            return False
        if not self._sm_was_eligible_to_fight_this_phase(root):
            logger.error("ERROR: A CEASELESS CAUSE: target must have been eligible to fight this phase")
            return False
        if self._sm_unit_is_engaged(root):
            logger.error("ERROR: A CEASELESS CAUSE: target must not be within Engagement Range")
            return False
        eligible = candidates or self._space_marines_godhammer_phase_unit_candidates(
            phase_name="Fight phase",
            require_infantry=True,
            require_fight_eligible=True,
            require_not_engaged=True,
        )
        if eligible and not self._sm_unit_in_candidates(root, eligible):
            logger.error("ERROR: A CEASELESS CAUSE: selected unit is not currently eligible")
            return False
        queue_move = getattr(self.game, "_queue_reactive_move_movement_decision", None) if self.game is not None else None
        if not callable(queue_move):
            logger.error("ERROR: A CEASELESS CAUSE: reactive move queue unavailable")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False
        request = queue_move(
            player=self.player,
            unit=root,
            max_distance=6,
            kind="a_ceaseless_cause",
            movement_type="move",
            source=str(getattr(stratagem, "name", "") or "A CEASELESS CAUSE"),
            allow_skip=True,
        )
        if request is None:
            logger.error("ERROR: A CEASELESS CAUSE: failed to queue move decision")
            return False

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: A CEASELESS CAUSE: %s can make a Normal move up to 6\".",
            getattr(root, "name", "Unit"),
        )
        return True

    def _use_space_marines_burning_vengeance(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "shooting phase":
            logger.error("ERROR: BURNING VENGEANCE: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is self.player:
            logger.error("ERROR: BURNING VENGEANCE: not opponent's Shooting phase")
            return False

        unit, candidates, enemy_unit, _embark_candidates, _embark_candidate_map, from_pending = self._sm_firestorm_context(
            "BURNING VENGEANCE",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: BURNING VENGEANCE: no target transport provided")
            return False
        root = self._sm_root(unit)
        attacker_root = self._sm_root(enemy_unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: BURNING VENGEANCE: target transport is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: BURNING VENGEANCE: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root) or not self._sm_is_transport_unit(root):
            logger.error("ERROR: BURNING VENGEANCE: target must be an ADEPTUS ASTARTES TRANSPORT")
            return False
        if candidates and not self._sm_unit_in_candidates(root, candidates):
            logger.error("ERROR: BURNING VENGEANCE: target is not currently eligible")
            return False
        if attacker_root is None:
            logger.error("ERROR: BURNING VENGEANCE: missing attacking unit context")
            return False
        if self._sm_owned_by_player(attacker_root, self.player):
            logger.error("ERROR: BURNING VENGEANCE: attacking unit must be an enemy unit")
            return False
        embarked = list(getattr(root, "transport_passengers", []) or [])
        if not embarked:
            logger.error("ERROR: BURNING VENGEANCE: no embarked units")
            return False
        if not from_pending and not isinstance(kwargs.get("hits_by_target"), dict):
            kwargs.setdefault("trigger", "unit_shooting_resolved")

        queue_fn = getattr(self.game, "_queue_transport_reactive_disembark_decisions", None) if self.game is not None else None
        if not callable(queue_fn):
            logger.error("ERROR: BURNING VENGEANCE: reactive disembark decision queue unavailable")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False
        requests = list(
            queue_fn(
                player=self.player,
                transport=root,
                enemy_unit=attacker_root,
                ability={"name": str(stratagem.name or "BURNING VENGEANCE")},
                trigger="unit_shooting_resolved",
                max_units=1,
            )
            or []
        )
        if not requests:
            logger.error("ERROR: BURNING VENGEANCE: no disembark decision was queued")
            return False
        enemy_id = str(get_entity_id(attacker_root) or "")
        for req in requests:
            req_ctx = dict(getattr(req, "context", {}) or {})
            req_ctx["reactive_disembark_then_shoot_enemy_only"] = True
            req_ctx["reactive_disembark_shoot_enemy_id"] = enemy_id
            req_ctx["reactive_disembark_shoot_source"] = str(stratagem.name or "BURNING VENGEANCE")
            req.context = req_ctx

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: BURNING VENGEANCE: queued disembark decision and follow-up reactive shooting into the attacking unit."
        )
        return True

    def _use_space_marines_crucible_of_battle(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name not in {"shooting phase", "fight phase"}:
            logger.error("ERROR: CRUCIBLE OF BATTLE: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if phase_name == "shooting phase" and active_player is not self.player:
            logger.error("ERROR: CRUCIBLE OF BATTLE: not your Shooting phase")
            return False

        unit, candidates, _enemy_unit, _embark_candidates, _embark_candidate_map, _from_pending = self._sm_firestorm_context(
            "CRUCIBLE OF BATTLE",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: CRUCIBLE OF BATTLE: no target unit provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: CRUCIBLE OF BATTLE: target unit is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: CRUCIBLE OF BATTLE: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root):
            logger.error("ERROR: CRUCIBLE OF BATTLE: target must be an ADEPTUS ASTARTES unit")
            return False
        if not self._sm_is_infantry_unit(root):
            logger.error("ERROR: CRUCIBLE OF BATTLE: target must be an INFANTRY unit")
            return False
        eligible = candidates or self._space_marines_firestorm_phase_unit_candidates(
            phase_name="Shooting phase" if phase_name == "shooting phase" else "Fight phase",
            require_infantry=True,
        )
        if eligible and not self._sm_unit_in_candidates(root, eligible):
            logger.error("ERROR: CRUCIBLE OF BATTLE: selected unit is not currently eligible")
            return False
        if phase_name == "shooting phase" and self._sm_selected_to_shoot_this_phase(root):
            logger.error("ERROR: CRUCIBLE OF BATTLE: target has already been selected to shoot this phase")
            return False
        if phase_name == "fight phase" and self._sm_selected_to_fight_this_phase(root):
            logger.error("ERROR: CRUCIBLE OF BATTLE: target has already been selected to fight this phase")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False

        mgr = self._sm_detachment_mgr()
        if self._is_firestorm_assault_force_detachment():
            apply_fn = getattr(mgr, "set_firestorm_crucible_of_battle", None) if mgr is not None else None
            detachment_label = "Firestorm Assault Force"
        elif self._is_forgefathers_seekers_detachment():
            apply_fn = getattr(mgr, "set_forgefathers_seekers_crucible_of_battle", None) if mgr is not None else None
            detachment_label = "Forgefather's Seekers"
        else:
            apply_fn = None
            detachment_label = "Space Marines"
        if not callable(apply_fn):
            logger.error("ERROR: CRUCIBLE OF BATTLE: %s detachment manager unavailable", detachment_label)
            return False
        phase_label = "Shooting phase" if phase_name == "shooting phase" else "Fight phase"
        applied = apply_fn(
            root,
            phase_name=phase_label,
            battle_round=int(getattr(self.game, "turn", 0) or 0) if self.game is not None else 0,
            player_id=str(getattr(self.player, "id", "") or ""),
            source=str(getattr(stratagem, "name", "") or "CRUCIBLE OF BATTLE"),
        )
        if not bool(applied):
            logger.error("ERROR: CRUCIBLE OF BATTLE: failed to apply wound bonus")
            return False

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: CRUCIBLE OF BATTLE: %s gains +1 to wound against the closest eligible target within 6\" this phase.",
            getattr(root, "name", "Unit"),
        )
        return True

    def _use_space_marines_immolation_protocols(self, stratagem: Any, **kwargs) -> bool:
        phase_name = str(kwargs.get("phase_name") or self._current_phase_name or "").strip().lower()
        if phase_name != "shooting phase":
            logger.error("ERROR: IMMOLATION PROTOCOLS: wrong phase")
            return False
        active_player = getattr(self.game, "get_current_player", lambda: None)() if self.game is not None else None
        if active_player is not self.player:
            logger.error("ERROR: IMMOLATION PROTOCOLS: not your Shooting phase")
            return False

        unit, candidates, _enemy_unit, _embark_candidates, _embark_candidate_map, _from_pending = self._sm_firestorm_context(
            "IMMOLATION PROTOCOLS",
            kwargs,
        )
        if unit is None:
            logger.error("ERROR: IMMOLATION PROTOCOLS: no target unit provided")
            return False
        root = self._sm_root(unit)
        if root is None:
            return False
        if not self._sm_owned_by_player(root, self.player):
            logger.error("ERROR: IMMOLATION PROTOCOLS: target unit is not yours")
            return False
        if not self._sm_on_battlefield(root, require_targetable=True):
            logger.error("ERROR: IMMOLATION PROTOCOLS: target must be on the battlefield and targetable")
            return False
        if not self._is_adeptus_astartes_unit(root):
            logger.error("ERROR: IMMOLATION PROTOCOLS: target must be an ADEPTUS ASTARTES unit")
            return False
        eligible = candidates or self._space_marines_firestorm_phase_unit_candidates(phase_name="Shooting phase")
        if eligible and not self._sm_unit_in_candidates(root, eligible):
            logger.error("ERROR: IMMOLATION PROTOCOLS: selected unit is not currently eligible")
            return False
        if self._sm_selected_to_shoot_this_phase(root):
            logger.error("ERROR: IMMOLATION PROTOCOLS: target has already been selected to shoot this phase")
            return False
        if not self._sm_spend_cp(self.player, stratagem, target_unit=root):
            return False

        source = str(getattr(stratagem, "name", "") or "IMMOLATION PROTOCOLS").strip() or "IMMOLATION PROTOCOLS"
        for model in self._sm_unit_models(root):
            is_alive_attr = getattr(model, "is_alive", True)
            is_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
            if not is_alive:
                continue
            model_id = str(get_entity_id(model) or "")
            for wargear in list(getattr(model, "wargear", []) or []):
                if wargear is None:
                    continue
                is_ranged = getattr(wargear, "is_ranged", None)
                if not callable(is_ranged) or not bool(is_ranged()):
                    continue
                is_torrent = getattr(wargear, "is_torrent", None)
                has_torrent = bool(callable(is_torrent) and is_torrent())
                if not has_torrent:
                    get_keywords = getattr(wargear, "get_keywords", None)
                    if callable(get_keywords):
                        keywords = {
                            str(keyword or "").strip().upper()
                            for keyword in list(get_keywords() or [])
                            if str(keyword or "").strip()
                        }
                        has_torrent = "TORRENT" in keywords
                if not has_torrent:
                    continue
                weapon_name = str(getattr(wargear, "name", "") or "").strip()
                if not weapon_name:
                    continue
                set_keywords = getattr(model, "set_temporary_weapon_keyword_bonuses", None)
                if callable(set_keywords):
                    set_keywords(
                        key=f"space_marines_immolation_protocols:{model_id}:{weapon_name}".lower(),
                        weapon_name=weapon_name,
                        keywords=["DEVASTATING WOUNDS"],
                        source=source,
                        expires_phase="SHOOTING_PHASE",
                        attack_type="ranged",
                    )

        self._sm_finalize_use(stratagem, dequeue=kwargs.get("dequeue") is True)
        logger.info(
            "INFO: IMMOLATION PROTOCOLS: %s grants [DEVASTATING WOUNDS] to Torrent ranged weapons this phase.",
            getattr(root, "name", "Unit"),
        )
        return True

